const resolveAccount = `-- name: ResolveAccount :one
SELECT u.id, u.public_id, u.email, u.role, p.name, p.supplier_id,
       COALESCE(active_workspace.org_id, 0)::bigint AS org_id,
       COALESCE(active_workspace.workspace_role, '')::text AS workspace_role
FROM account_sessions s
JOIN account_users u ON u.id = s.user_id
JOIN account_profiles p ON p.user_id = u.id
LEFT JOIN LATERAL (
    SELECT o.id AS org_id, m.role AS workspace_role
    FROM organization_members m
    JOIN organizations o ON o.id = m.org_id
    WHERE m.user_id = u.id
      AND m.status = 'active'
      AND NOT m.manual_disabled
      AND NOT m.quota_suspended
      AND o.dissolved_at IS NULL
    ORDER BY (o.id = p.active_org_id) DESC NULLS LAST,
             (m.role = 'owner') DESC, o.id ASC
    LIMIT 1
) active_workspace ON true
WHERE s.token_hash = $1
  AND s.expires_at > clock_timestamp()
  AND u.disabled_at IS NULL
LIMIT 1
`

type ResolveAccountRow struct {
	ID            int64
	PublicID      string
	Email         string
	Role          string
	Name          string
	SupplierID    string
	OrgID         int64
	WorkspaceRole string
}

func (q *Queries) ResolveAccount(ctx context.Context, tokenHash string) (ResolveAccountRow, error) {
	row := q.db.QueryRow(ctx, resolveAccount, tokenHash)
	var i ResolveAccountRow
	err := row.Scan(
		&i.ID,
		&i.PublicID,
		&i.Email,
		&i.Role,
		&i.Name,
		&i.SupplierID,
		&i.OrgID,
		&i.WorkspaceRole,
	)
	return i, err
}

const resolveStacked = `-- name: ResolveStacked :many
SELECT s.token_hash, u.id AS user_id, u.public_id AS uuid, u.email, p.name,
       CASE WHEN p.avatar_bytes IS NOT NULL THEN p.avatar_updated_at_ms END AS avatar_revision
FROM account_sessions s
JOIN account_users u ON u.id = s.user_id
JOIN account_profiles p ON p.user_id = u.id
WHERE s.token_hash = ANY($1::text[])
  AND s.expires_at > clock_timestamp()
  AND u.disabled_at IS NULL
`

type ResolveStackedRow struct {
	TokenHash      string
	UserID         int64
	Uuid           string
	Email          string
	Name           string
	AvatarRevision interface{}
}

func (q *Queries) ResolveStacked(ctx context.Context, dollar_1 []string) ([]ResolveStackedRow, error) {
	rows, err := q.db.Query(ctx, resolveStacked, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ResolveStackedRow
	for rows.Next() {
		var i ResolveStackedRow
		if err := rows.Scan(
			&i.TokenHash,
			&i.UserID,
			&i.Uuid,
			&i.Email,
			&i.Name,
			&i.AvatarRevision,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

